const msg = $input.first().json.message;
if (!msg || !msg.text) return [];
const text = msg.text;
// Простой хеш-код текста
const hash = text.split('').reduce((a,b)=>{a=((a<<5)-a)+b.charCodeAt(0);return a&a},0).toString(16);
return [{ json: { text, hash, chatId: msg.chat.id, messageId: msg.message_id } }];

