const seen = new Set(JSON.parse(global.$getWorkflowStaticData().seenHashes || '[]'));
const newItems = [];
for (const item of items) {
  if (!seen.has(item.json.hash)) {
    seen.add(item.json.hash);
    newItems.push(item);
  }
}
global.$getWorkflowStaticData().seenHashes = JSON.stringify(Array.from(seen).slice(-500));
return newItems;

