let text = item.json.text;
// Убираем все URL
text = text.replace(/https?:\/\/[^\s]+/gi, '');
// Убираем @упоминания
text = text.replace(/@[a-zA-Z0-9_]+/gi, '');
// Убираем t.me
text = text.replace(/t\.me\/\w+/gi, '');
// Убираем лишние пробелы
text = text.replace(/\s{2,}/g, ' ');
return [{ json: { text: text.trim(), ...item.json } }];

// Fallback для ситуации без AI API
const text = item.json.text;
return [{ json: { text: text, ...item.json } }];
